-- Rôle de chaque semaine dans le plan (translations_json.weeks, 9 langues). Rejouable.
UPDATE public.training_plans SET translations_json = jsonb_set(coalesce(translations_json, '{}'::jsonb), '{weeks}', '{"1": {"fr": "Adaptation : blocs TT de 15 à 20'', tempo court et 90'' de sortie longue. On installe la position à basse intensité avant douze semaines de progression.", "en": "Adaptation: 15 to 20'' TT blocks, short tempo and a 90'' long ride. We settle the position at low intensity before twelve weeks of progression.", "es": "Adaptación: bloques de 15 a 20'' en TT, tempo corto y 90'' de salida larga. Asentamos la posición a baja intensidad antes de doce semanas de progresión.", "it": "Adattamento: blocchi in TT da 15 a 20'', ritmo tempo breve e 90'' di uscita lunga. Fissiamo la posizione a bassa intensità prima di dodici settimane di progressione.", "pt": "Adaptação: blocos em TT de 15 a 20'', ritmo tempo curto e 90'' de treino longo. Fixamos a posição em baixa intensidade antes de doze semanas de progressão.", "de": "Anpassung: TT-Blöcke von 15 bis 20'', kurzes Tempo und 90'' lange Fahrt. Wir festigen die Position bei niedriger Intensität vor zwölf Wochen Aufbau.", "nl": "Aanpassing: TT-blokken van 15 tot 20'', kort tempo en een lange rit van 90''. We leren de houding aan op lage intensiteit voor twaalf weken opbouw.", "ja": "適応：15〜20''のTTブロック、短いテンポ、90''のロングライド。12週間の積み上げの前に、低強度でポジションを定着させます。", "tr": "Uyum: 15-20''lik TT blokları, kısa tempo ve 90'' uzun sürüş. On iki haftalık gelişimden önce pozisyonu düşük yoğunlukta oturtuyoruz."}, "2": {"fr": "Les blocs s''allongent de 5'' et la sortie longue approche les 2 h. La progression suit l''adaptation du cou et du dos, pas celle du cardio.", "en": "Blocks get 5'' longer and the long ride approaches 2 h. Progress follows how your neck and back adapt, not your cardio.", "es": "Los bloques se alargan 5'' y la salida larga se acerca a las 2 h. La progresión sigue la adaptación del cuello y la espalda, no la del cardio.", "it": "I blocchi si allungano di 5'' e l''uscita lunga si avvicina alle 2 h. La progressione segue l''adattamento di collo e schiena, non quello del cuore.", "pt": "Os blocos ganham 5'' e o treino longo se aproxima das 2 h. A progressão acompanha a adaptação do pescoço e das costas, não a do cardio.", "de": "Die Blöcke werden 5'' länger und die lange Fahrt nähert sich 2 h. Der Aufbau folgt der Anpassung von Nacken und Rücken, nicht der des Herz-Kreislauf-Systems.", "nl": "De blokken worden 5'' langer en de lange rit nadert 2 u. De opbouw volgt de aanpassing van nek en rug, niet die van je conditie.", "ja": "ブロックが5''伸び、ロングライドは2時間に近づきます。進み方は心肺ではなく、首と背中の適応に合わせます。", "tr": "Bloklar 5'' uzuyor ve uzun sürüş 2 saate yaklaşıyor. İlerleme kalbin değil, boyun ve sırtın uyumunu izliyor."}, "3": {"fr": "Fin du premier cycle : 2×30'' en TT, tempo 3×15'', 2 h 15 de sortie longue. Une surcharge qui fixe la base du plan.", "en": "End of the first cycle: 2×30'' in TT, tempo 3×15'', a 2 h 15 long ride. An overload that sets the base of the plan.", "es": "Fin del primer ciclo: 2×30'' en TT, tempo 3×15'', 2 h 15 de salida larga. Una sobrecarga que fija la base del plan.", "it": "Fine del primo ciclo: 2×30'' in TT, ritmo tempo 3×15'', 2 h 15 di uscita lunga. Un sovraccarico che fissa la base del piano.", "pt": "Fim do primeiro ciclo: 2×30'' em TT, ritmo tempo 3×15'', 2 h 15 de treino longo. Uma sobrecarga que fixa a base do plano.", "de": "Ende des ersten Zyklus: 2×30'' in TT, Tempo 3×15'', 2 h 15 lange Fahrt. Eine Belastungsspitze, die die Basis des Plans festigt.", "nl": "Einde van de eerste cyclus: 2×30'' in TT, tempo 3×15'', lange rit van 2 u 15. Een piekbelasting die de basis van het plan legt.", "ja": "第1サイクルの終わり：TTで2×30''、テンポ3×15''、2時間15分のロングライド。プランの土台を固めるオーバーロードです。", "tr": "İlk döngünün sonu: TT''de 2×30'', tempo 3×15'', 2 sa 15 uzun sürüş. Planın temelini sabitleyen bir yüklenme."}, "4": {"fr": "Allègement : une séance en moins, blocs ramenés à 20''. Tu récupères avant de passer aux blocs d''un seul tenant.", "en": "Lighter week: one session fewer, blocks back to 20''. You recover before moving on to unbroken blocks.", "es": "Semana más ligera: una sesión menos, bloques reducidos a 20''. Recuperas antes de pasar a los bloques de una sola vez.", "it": "Scarico: una seduta in meno, blocchi riportati a 20''. Recuperi prima di passare ai blocchi tutti d''un fiato.", "pt": "Alívio: uma sessão a menos, blocos de volta a 20''. Você recupera antes de passar para os blocos de uma vez só.", "de": "Entlastung: eine Einheit weniger, Blöcke zurück auf 20''. Du erholst dich, bevor die Blöcke am Stück kommen.", "nl": "Afbouw: één training minder, blokken terug naar 20''. Je herstelt voordat de blokken aan één stuk komen.", "ja": "軽めの週：セッションを1回減らし、ブロックは20''に戻します。一続きのブロックに移る前に回復します。", "tr": "Hafifletme: bir antrenman eksik, bloklar 20'' oluyor. Kesintisiz bloklara geçmeden önce toparlanıyorsun."}, "5": {"fr": "Deuxième cycle : 45'' d''affilée en TT. On passe des blocs fractionnés à la durée continue, celle des courses longues.", "en": "Second cycle: 45'' straight in TT. We move from split blocks to continuous duration, the kind long races require.", "es": "Segundo ciclo: 45'' seguidos en TT. Pasamos de bloques fraccionados a la duración continua, la de las carreras largas.", "it": "Secondo ciclo: 45'' di fila in TT. Si passa dai blocchi frazionati alla durata continua, quella delle gare lunghe.", "pt": "Segundo ciclo: 45'' seguidos em TT. Passamos dos blocos fracionados para a duração contínua, a das provas longas.", "de": "Zweiter Zyklus: 45'' am Stück in TT. Wir gehen von unterteilten Blöcken zur durchgehenden Dauer über, der von langen Rennen.", "nl": "Tweede cyclus: 45'' aan één stuk in TT. We gaan van opgedeelde blokken naar een doorlopende duur, die van lange wedstrijden.", "ja": "第2サイクル：TTで45''連続。分割ブロックから、長いレースに必要な連続した時間へ移ります。", "tr": "İkinci döngü: TT''de kesintisiz 45''. Bölünmüş bloklardan uzun yarışların gerektirdiği kesintisiz süreye geçiyoruz."}, "6": {"fr": "Une heure d''affilée en TT, tempo 2×25''. La position devient une habitude ; c''est souvent la tête qui lâche en premier, surveille-la.", "en": "One hour straight in TT, tempo 2×25''. The position becomes a habit; it''s often your head that gives way first, so watch it.", "es": "Una hora seguida en TT, tempo 2×25''. La posición se convierte en hábito; a menudo es la cabeza lo primero que cede, vigílala.", "it": "Un''ora di fila in TT, ritmo tempo 2×25''. La posizione diventa un''abitudine; spesso è la testa a cedere per prima, controllala.", "pt": "Uma hora seguida em TT, ritmo tempo 2×25''. A posição vira hábito; muitas vezes é a cabeça que cede primeiro, fique de olho nela.", "de": "Eine Stunde am Stück in TT, Tempo 2×25''. Die Position wird zur Gewohnheit; oft gibt der Kopf als Erstes nach, achte auf ihn.", "nl": "Een uur aan één stuk in TT, tempo 2×25''. De houding wordt een gewoonte; vaak geeft je hoofd als eerste op, let erop.", "ja": "TTで1時間連続、テンポ2×25''。ポジションが習慣になります。最初に崩れるのはたいてい頭なので注意して。", "tr": "TT''de kesintisiz bir saat, tempo 2×25''. Pozisyon alışkanlık haline geliyor; ilk bırakan çoğu zaman baş olur, ona dikkat et."}, "7": {"fr": "Pic du deuxième cycle : 75'' d''affilée, 2×45'' et 2 h 35 de sortie longue.", "en": "Peak of the second cycle: 75'' straight, 2×45'' and a 2 h 35 long ride.", "es": "Pico del segundo ciclo: 75'' seguidos, 2×45'' y 2 h 35 de salida larga.", "it": "Picco del secondo ciclo: 75'' di fila, 2×45'' e 2 h 35 di uscita lunga.", "pt": "Pico do segundo ciclo: 75'' seguidos, 2×45'' e 2 h 35 de treino longo.", "de": "Höhepunkt des zweiten Zyklus: 75'' am Stück, 2×45'' und 2 h 35 lange Fahrt.", "nl": "Hoogtepunt van de tweede cyclus: 75'' aan één stuk, 2×45'' en een lange rit van 2 u 35.", "ja": "第2サイクルのピーク：75''連続、2×45''、2時間35分のロングライド。", "tr": "İkinci döngünün zirvesi: kesintisiz 75'', 2×45'' ve 2 sa 35 uzun sürüş."}, "8": {"fr": "Allègement : 90'' d''affilée sur la sortie longue mais une charge globale réduite. Tu assimiles avant le dernier cycle.", "en": "Lighter week: 90'' straight on the long ride but a reduced overall load. You absorb the work before the final cycle.", "es": "Semana más ligera: 90'' seguidos en la salida larga pero con una carga global reducida. Asimilas antes del último ciclo.", "it": "Scarico: 90'' di fila nell''uscita lunga ma un carico complessivo ridotto. Assimili prima dell''ultimo ciclo.", "pt": "Alívio: 90'' seguidos no treino longo, mas uma carga total reduzida. Você assimila antes do último ciclo.", "de": "Entlastung: 90'' am Stück auf der langen Fahrt, aber insgesamt weniger Belastung. Du verarbeitest vor dem letzten Zyklus.", "nl": "Afbouw: 90'' aan één stuk tijdens de lange rit, maar een lagere totale belasting. Je verwerkt voor de laatste cyclus.", "ja": "軽めの週：ロングライドで90''連続、ただし全体の負荷は減らします。最後のサイクルの前に吸収します。", "tr": "Hafifletme: uzun sürüşte kesintisiz 90'' ama genel yük azaltılmış. Son döngüden önce özümsüyorsun."}, "9": {"fr": "Troisième cycle : 80'' d''affilée en TT et tempo 3×25''. On entre dans les durées d''un vélo d''Ironman.", "en": "Third cycle: 80'' straight in TT and tempo 3×25''. We enter the durations of an Ironman bike leg.", "es": "Tercer ciclo: 80'' seguidos en TT y tempo 3×25''. Entramos en las duraciones del segmento ciclista de un Ironman.", "it": "Terzo ciclo: 80'' di fila in TT e ritmo tempo 3×25''. Si entra nelle durate della frazione bici di un Ironman.", "pt": "Terceiro ciclo: 80'' seguidos em TT e ritmo tempo 3×25''. Entramos nas durações do ciclismo de um Ironman.", "de": "Dritter Zyklus: 80'' am Stück in TT und Tempo 3×25''. Wir erreichen die Dauer einer Ironman-Radstrecke.", "nl": "Derde cyclus: 80'' aan één stuk in TT en tempo 3×25''. We komen in de duur van een Ironman-fietsproef.", "ja": "第3サイクル：TTで80''連続とテンポ3×25''。アイアンマンのバイクの時間に入っていきます。", "tr": "Üçüncü döngü: TT''de kesintisiz 80'' ve tempo 3×25''. Bir Ironman bisikletinin sürelerine giriyoruz."}, "10": {"fr": "90'' d''affilée, tempo 2×40'', 2 h d''affilée en sortie longue. L''endurance de position devient spécifique à la longue distance.", "en": "90'' straight, tempo 2×40'', 2 h straight on the long ride. Your position endurance becomes specific to long distance.", "es": "90'' seguidos, tempo 2×40'', 2 h seguidas en la salida larga. La resistencia en posición se vuelve específica de la larga distancia.", "it": "90'' di fila, ritmo tempo 2×40'', 2 h di fila nell''uscita lunga. La resistenza in posizione diventa specifica per la lunga distanza.", "pt": "90'' seguidos, ritmo tempo 2×40'', 2 h seguidas no treino longo. A resistência na posição fica específica para a longa distância.", "de": "90'' am Stück, Tempo 2×40'', 2 h am Stück auf der langen Fahrt. Die Positionsausdauer wird spezifisch für die Langdistanz.", "nl": "90'' aan één stuk, tempo 2×40'', 2 u aan één stuk tijdens de lange rit. Het uithoudingsvermogen in houding wordt specifiek voor de lange afstand.", "ja": "90''連続、テンポ2×40''、ロングライドで2時間連続。ポジションの持久力がロングディスタンスに特化していきます。", "tr": "Kesintisiz 90'', tempo 2×40'', uzun sürüşte kesintisiz 2 sa. Pozisyon dayanıklılığı uzun mesafeye özgü hale geliyor."}, "11": {"fr": "Pic du plan : 100'' d''affilée, 60'' au tempo et 2 h 20 d''affilée en TT. C''est la semaine qui valide l''objectif.", "en": "Peak of the plan: 100'' straight, 60'' at tempo and 2 h 20 straight in TT. This is the week that validates the goal.", "es": "Pico del plan: 100'' seguidos, 60'' a tempo y 2 h 20 seguidas en TT. Es la semana que valida el objetivo.", "it": "Picco del piano: 100'' di fila, 60'' al ritmo tempo e 2 h 20 di fila in TT. È la settimana che convalida l''obiettivo.", "pt": "Pico do plano: 100'' seguidos, 60'' no ritmo tempo e 2 h 20 seguidas em TT. É a semana que valida o objetivo.", "de": "Höhepunkt des Plans: 100'' am Stück, 60'' im Tempo und 2 h 20 am Stück in TT. Diese Woche bestätigt das Ziel.", "nl": "Hoogtepunt van het plan: 100'' aan één stuk, 60'' op tempo en 2 u 20 aan één stuk in TT. Deze week bevestigt het doel.", "ja": "プランのピーク：100''連続、テンポで60''、TTで2時間20分連続。目標を検証する週です。", "tr": "Planın zirvesi: kesintisiz 100'', tempoda 60'' ve TT''de kesintisiz 2 sa 20. Hedefi doğrulayan hafta bu."}, "12": {"fr": "Affûtage : charge réduite, 90'' en TT pour garder la position. Tu termines frais et prêt pour une épreuve longue.", "en": "Taper: reduced load, 90'' in TT to keep the position. You finish fresh and ready for a long event.", "es": "Puesta a punto: carga reducida, 90'' en TT para mantener la posición. Terminas fresco y listo para una prueba larga.", "it": "Scarico: carico ridotto, 90'' in TT per mantenere la posizione. Finisci fresco e pronto per una gara lunga.", "pt": "Polimento: carga reduzida, 90'' em TT para manter a posição. Você termina descansado e pronto para uma prova longa.", "de": "Tapering: reduzierte Belastung, 90'' in TT, um die Position zu erhalten. Du beendest den Plan frisch und bereit für einen langen Wettkampf.", "nl": "Taperen: lagere belasting, 90'' in TT om de houding te onderhouden. Je eindigt fris en klaar voor een lange wedstrijd.", "ja": "調整（テーパー）：負荷を減らし、ポジションを保つためにTTで90''。フレッシュな状態で終え、長いレースへの準備が整います。", "tr": "Yarış öncesi yük azaltma: azaltılmış yük, pozisyonu korumak için TT''de 90''. Taze bitiriyorsun ve uzun bir yarışa hazırsın."}}'::jsonb) WHERE name_key = 'endurance_tt_12w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(coalesce(translations_json, '{}'::jsonb), '{weeks}', '{"1": {"fr": "Découverte : sprints de 15'''', relances d''1'' et premiers 30/30, tous en TT. On apprend le geste explosif en position.", "en": "Discovery: 15'''' sprints, one-minute surges and first 30/30s, all in TT. We learn the explosive movement in position.", "es": "Descubrimiento: sprints de 15'''', cambios de ritmo de 1'' y primeros 30/30, todo en TT. Aprendemos el gesto explosivo en posición.", "it": "Scoperta: sprint di 15'''', rilanci di 1'' e primi 30/30, tutti in TT. Si impara il gesto esplosivo in posizione.", "pt": "Descoberta: sprints de 15'''', retomadas de 1'' e primeiros 30/30, todos em TT. Aprendemos o gesto explosivo na posição.", "de": "Kennenlernen: 15''''-Sprints, Antritte à 1'' und erste 30/30, alles in TT. Wir lernen die explosive Bewegung in Position.", "nl": "Kennismaking: sprints van 15'''', versnellingen van 1'' en de eerste 30/30''s, allemaal in TT. We leren de explosieve beweging in houding.", "ja": "導入：15''''のスプリント、1''の加速、最初の30/30、すべてTTで。ポジションのまま爆発的な動きを学びます。", "tr": "Keşif: 15'''' sprintler, 1'' ataklar ve ilk 30/30''lar, hepsi TT''de. Pozisyonda patlayıcı hareketi öğreniyoruz."}, "2": {"fr": "Plus de répétitions. La capacité anaérobie se développe ; rester en TT quand le souffle sature devient le défi.", "en": "More reps. Anaerobic capacity develops; staying in TT when your breathing maxes out becomes the challenge.", "es": "Más repeticiones. La capacidad anaeróbica se desarrolla; mantenerte en TT cuando el aliento se satura se convierte en el reto.", "it": "Più ripetute. La capacità anaerobica si sviluppa; restare in TT quando il fiato è saturo diventa la sfida.", "pt": "Mais repetições. A capacidade anaeróbia se desenvolve; ficar em TT quando o fôlego satura vira o desafio.", "de": "Mehr Wiederholungen. Die anaerobe Kapazität entwickelt sich; in TT zu bleiben, wenn der Atem am Limit ist, wird zur Herausforderung.", "nl": "Meer herhalingen. De anaerobe capaciteit ontwikkelt zich; in TT blijven als je adem verzadigd raakt wordt de uitdaging.", "ja": "反復が増えます。無酸素能力が伸び、呼吸が限界に達してもTTを保つことが課題になります。", "tr": "Daha fazla tekrar. Anaerobik kapasite gelişiyor; nefes doyduğunda TT''de kalmak asıl zorluk oluyor."}, "3": {"fr": "Surcharge du premier cycle : 12 sprints, 10 relances, 3 séries de 30/30.", "en": "First-cycle overload: 12 sprints, 10 surges, 3 sets of 30/30.", "es": "Sobrecarga del primer ciclo: 12 sprints, 10 cambios de ritmo, 3 series de 30/30.", "it": "Sovraccarico del primo ciclo: 12 sprint, 10 rilanci, 3 serie di 30/30.", "pt": "Sobrecarga do primeiro ciclo: 12 sprints, 10 retomadas, 3 séries de 30/30.", "de": "Belastungsspitze des ersten Zyklus: 12 Sprints, 10 Antritte, 3 Serien 30/30.", "nl": "Piekbelasting van de eerste cyclus: 12 sprints, 10 versnellingen, 3 series 30/30.", "ja": "第1サイクルのオーバーロード：スプリント12本、加速10本、30/30を3セット。", "tr": "İlk döngünün yüklenmesi: 12 sprint, 10 atak, 3 set 30/30."}, "4": {"fr": "Allègement : moins de répétitions, une endurance TT. Les sprints doivent sortir plus fort qu''en semaine 1.", "en": "Lighter week: fewer reps, one TT endurance ride. Your sprints should come out stronger than in week 1.", "es": "Semana más ligera: menos repeticiones, una resistencia en TT. Los sprints deben salir más fuertes que en la semana 1.", "it": "Scarico: meno ripetute, un endurance in TT. Gli sprint devono uscire più forti che in settimana 1.", "pt": "Alívio: menos repetições, um endurance em TT. Os sprints devem sair mais fortes que na semana 1.", "de": "Entlastung: weniger Wiederholungen, eine TT-Grundlageneinheit. Die Sprints sollten stärker ausfallen als in Woche 1.", "nl": "Afbouw: minder herhalingen, één duurtraining in TT. De sprints moeten krachtiger zijn dan in week 1.", "ja": "軽めの週：反復を減らし、TTでのエンデュランス。スプリントは1週目より強く出るはずです。", "tr": "Hafifletme: daha az tekrar, bir TT dayanıklılık. Sprintler 1. haftadakinden daha güçlü çıkmalı."}, "5": {"fr": "Deuxième cycle : sprints de 20'''' à 175 %, relances à 125 %. Plus long et plus fort.", "en": "Second cycle: 20'''' sprints at 175 %, surges at 125 %. Longer and harder.", "es": "Segundo ciclo: sprints de 20'''' al 175 %, cambios de ritmo al 125 %. Más largos y más fuertes.", "it": "Secondo ciclo: sprint di 20'''' al 175 %, rilanci al 125 %. Più lunghi e più forti.", "pt": "Segundo ciclo: sprints de 20'''' a 175 %, retomadas a 125 %. Mais longos e mais fortes.", "de": "Zweiter Zyklus: 20''''-Sprints bei 175 %, Antritte bei 125 %. Länger und stärker.", "nl": "Tweede cyclus: sprints van 20'''' op 175 %, versnellingen op 125 %. Langer en harder.", "ja": "第2サイクル：175 %で20''''のスプリント、125 %で加速。より長く、より強く。", "tr": "İkinci döngü: %175''te 20'''' sprintler, %125''te ataklar. Daha uzun ve daha güçlü."}, "6": {"fr": "10 sprints, 10 relances, 3×10 30/30. Récupère complètement entre les sprints : la puissance max se travaille frais.", "en": "10 sprints, 10 surges, 3×10 30/30. Recover fully between sprints: max power is trained fresh.", "es": "10 sprints, 10 cambios de ritmo, 3×10 30/30. Recupera por completo entre sprints: la potencia máxima se trabaja fresco.", "it": "10 sprint, 10 rilanci, 3×10 30/30. Recupera completamente tra gli sprint: la potenza massima si allena da freschi.", "pt": "10 sprints, 10 retomadas, 3×10 30/30. Recupere completamente entre os sprints: a potência máxima se treina descansado.", "de": "10 Sprints, 10 Antritte, 3×10 30/30. Erhol dich zwischen den Sprints vollständig: Maximalleistung trainiert man frisch.", "nl": "10 sprints, 10 versnellingen, 3×10 30/30. Herstel volledig tussen de sprints: maximaal vermogen train je fris.", "ja": "スプリント10本、加速10本、3×10 30/30。スプリント間は完全に回復すること：最大パワーはフレッシュな状態で鍛えます。", "tr": "10 sprint, 10 atak, 3×10 30/30. Sprintler arasında tamamen toparlan: maksimum güç taze çalışılır."}, "7": {"fr": "Pic du deuxième cycle : 12 sprints à 180 %, 12 relances, 4 séries de 30/30.", "en": "Peak of the second cycle: 12 sprints at 180 %, 12 surges, 4 sets of 30/30.", "es": "Pico del segundo ciclo: 12 sprints al 180 %, 12 cambios de ritmo, 4 series de 30/30.", "it": "Picco del secondo ciclo: 12 sprint al 180 %, 12 rilanci, 4 serie di 30/30.", "pt": "Pico do segundo ciclo: 12 sprints a 180 %, 12 retomadas, 4 séries de 30/30.", "de": "Höhepunkt des zweiten Zyklus: 12 Sprints bei 180 %, 12 Antritte, 4 Serien 30/30.", "nl": "Hoogtepunt van de tweede cyclus: 12 sprints op 180 %, 12 versnellingen, 4 series 30/30.", "ja": "第2サイクルのピーク：180 %でスプリント12本、加速12本、30/30を4セット。", "tr": "İkinci döngünün zirvesi: %180''de 12 sprint, 12 atak, 4 set 30/30."}, "8": {"fr": "Allègement avant le dernier cycle. La fraîcheur fait ressortir le gain des huit premières semaines.", "en": "Lighter week before the final cycle. Freshness brings out the gain from the first eight weeks.", "es": "Semana más ligera antes del último ciclo. La frescura hace aflorar la mejora de las ocho primeras semanas.", "it": "Scarico prima dell''ultimo ciclo. La freschezza fa emergere il progresso delle prime otto settimane.", "pt": "Alívio antes do último ciclo. A disposição faz aparecer o ganho das oito primeiras semanas.", "de": "Entlastung vor dem letzten Zyklus. Die Frische macht den Fortschritt der ersten acht Wochen sichtbar.", "nl": "Afbouw voor de laatste cyclus. De frisheid maakt de winst van de eerste acht weken zichtbaar.", "ja": "最後のサイクルの前の軽めの週。フレッシュさが最初の8週間の成果を引き出します。", "tr": "Son döngüden önce hafifletme. Tazelik ilk sekiz haftanın kazancını ortaya çıkarıyor."}, "9": {"fr": "Troisième cycle : même intensité qu''en semaine 7 mais des 30/30 plus longs (4×10). On consolide la répétition des efforts au-dessus du seuil en TT.", "en": "Third cycle: same intensity as in week 7 but longer 30/30s (4×10). We consolidate repeated efforts above threshold in TT.", "es": "Tercer ciclo: misma intensidad que en la semana 7 pero 30/30 más largos (4×10). Consolidamos la repetición de esfuerzos por encima del umbral en TT.", "it": "Terzo ciclo: stessa intensità della settimana 7 ma 30/30 più lunghi (4×10). Consolidiamo la ripetizione degli sforzi sopra soglia in TT.", "pt": "Terceiro ciclo: mesma intensidade da semana 7, mas 30/30 mais longos (4×10). Consolidamos a repetição dos esforços acima do limiar em TT.", "de": "Dritter Zyklus: gleiche Intensität wie in Woche 7, aber längere 30/30 (4×10). Wir festigen wiederholte Belastungen über der Schwelle in TT.", "nl": "Derde cyclus: dezelfde intensiteit als in week 7, maar langere 30/30''s (4×10). We consolideren herhaalde inspanningen boven de drempel in TT.", "ja": "第3サイクル：7週目と同じ強度で、30/30はより長く（4×10）。TTで閾値を超える努力の繰り返しを固めます。", "tr": "Üçüncü döngü: 7. haftayla aynı yoğunluk ama daha uzun 30/30''lar (4×10). TT''de eşiğin üstündeki eforların tekrarını pekiştiriyoruz."}, "10": {"fr": "14 sprints, 14 relances et 70'' d''endurance TT : volume maximal d''efforts explosifs en position.", "en": "14 sprints, 14 surges and 70'' of TT endurance: maximum volume of explosive efforts in position.", "es": "14 sprints, 14 cambios de ritmo y 70'' de resistencia en TT: volumen máximo de esfuerzos explosivos en posición.", "it": "14 sprint, 14 rilanci e 70'' di endurance in TT: volume massimo di sforzi esplosivi in posizione.", "pt": "14 sprints, 14 retomadas e 70'' de endurance em TT: volume máximo de esforços explosivos na posição.", "de": "14 Sprints, 14 Antritte und 70'' TT-Grundlage: maximaler Umfang explosiver Belastungen in Position.", "nl": "14 sprints, 14 versnellingen en 70'' duur in TT: maximaal volume aan explosieve inspanningen in houding.", "ja": "スプリント14本、加速14本、TTでのエンデュランス70''：ポジションのまま行う爆発的努力のボリュームが最大に。", "tr": "14 sprint, 14 atak ve 70'' TT dayanıklılık: pozisyonda maksimum patlayıcı efor hacmi."}, "11": {"fr": "Pic du plan : 14 sprints, 14 relances, 5 séries de 30/30. La semaine la plus exigeante du programme.", "en": "Peak of the plan: 14 sprints, 14 surges, 5 sets of 30/30. The most demanding week of the program.", "es": "Pico del plan: 14 sprints, 14 cambios de ritmo, 5 series de 30/30. La semana más exigente del programa.", "it": "Picco del piano: 14 sprint, 14 rilanci, 5 serie di 30/30. La settimana più impegnativa del programma.", "pt": "Pico do plano: 14 sprints, 14 retomadas, 5 séries de 30/30. A semana mais exigente do programa.", "de": "Höhepunkt des Plans: 14 Sprints, 14 Antritte, 5 Serien 30/30. Die anspruchsvollste Woche des Programms.", "nl": "Hoogtepunt van het plan: 14 sprints, 14 versnellingen, 5 series 30/30. De zwaarste week van het programma.", "ja": "プランのピーク：スプリント14本、加速14本、30/30を5セット。プログラムで最も厳しい週です。", "tr": "Planın zirvesi: 14 sprint, 14 atak, 5 set 30/30. Programın en zorlu haftası."}, "12": {"fr": "Affûtage : volume minimal, intensité intacte. Ta puissance max en TT doit être au plus haut.", "en": "Taper: minimal volume, intensity intact. Your max power in TT should be at its highest.", "es": "Puesta a punto: volumen mínimo, intensidad intacta. Tu potencia máxima en TT debe estar en su punto más alto.", "it": "Scarico: volume minimo, intensità intatta. La tua potenza massima in TT deve essere al massimo.", "pt": "Polimento: volume mínimo, intensidade intacta. Sua potência máxima em TT deve estar no auge.", "de": "Tapering: minimaler Umfang, Intensität unverändert. Deine Maximalleistung in TT sollte auf dem Höchststand sein.", "nl": "Taperen: minimaal volume, intensiteit intact. Je maximale vermogen in TT moet op zijn hoogst zijn.", "ja": "調整（テーパー）：ボリュームは最小、強度はそのまま。TTでの最大パワーは最高の状態にあるはずです。", "tr": "Yarış öncesi yük azaltma: minimum hacim, yoğunluk aynen. TT''deki maksimum gücün en yüksek seviyede olmalı."}}'::jsonb) WHERE name_key = 'sprint_tt_12w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(coalesce(translations_json, '{}'::jsonb), '{weeks}', '{"1": {"fr": "Mise en route : sweet spot, seuil et puissance critique sur des blocs courts, tout en TT.", "en": "Getting started: sweet spot, threshold and critical power on short blocks, all in TT.", "es": "Puesta en marcha: sweet spot, umbral y potencia crítica en bloques cortos, todo en TT.", "it": "Avvio: sweet spot, soglia e potenza critica su blocchi brevi, tutto in TT.", "pt": "Início: sweet spot, limiar e potência crítica em blocos curtos, tudo em TT.", "de": "Einstieg: Sweet Spot, Schwelle und kritische Leistung auf kurzen Blöcken, alles in TT.", "nl": "Instap: sweet spot, drempel en kritisch vermogen op korte blokken, alles in TT.", "ja": "導入：短いブロックでスイートスポット、閾値、クリティカルパワー、すべてTTで。", "tr": "Başlangıç: kısa bloklarda sweet spot, eşik ve kritik güç, hepsi TT''de."}, "2": {"fr": "Les blocs s''allongent et les sur-sous apparaissent : changer d''intensité sans bouger de position.", "en": "Blocks get longer and over-unders appear: changing intensity without moving out of position.", "es": "Los bloques se alargan y aparecen los sobre-bajo: cambiar de intensidad sin moverte de la posición.", "it": "I blocchi si allungano e compaiono i sopra-sotto: cambiare intensità senza muoversi dalla posizione.", "pt": "Os blocos se alongam e aparecem os acima-abaixo: mudar de intensidade sem sair da posição.", "de": "Die Blöcke werden länger und die Over-Under kommen: die Intensität wechseln, ohne die Position zu verändern.", "nl": "De blokken worden langer en de over-unders verschijnen: van intensiteit wisselen zonder je houding te veranderen.", "ja": "ブロックが伸び、オーバーアンダーが登場：ポジションを動かさずに強度を変えます。", "tr": "Bloklar uzuyor ve üst-altlar geliyor: pozisyonu bozmadan yoğunluk değiştirmek."}, "3": {"fr": "Surcharge du premier cycle : 2×20'' sweet spot, 3×12'' seuil, 5×4'' puissance critique.", "en": "First-cycle overload: 2×20'' sweet spot, 3×12'' threshold, 5×4'' critical power.", "es": "Sobrecarga del primer ciclo: 2×20'' sweet spot, 3×12'' umbral, 5×4'' potencia crítica.", "it": "Sovraccarico del primo ciclo: 2×20'' sweet spot, 3×12'' soglia, 5×4'' potenza critica.", "pt": "Sobrecarga do primeiro ciclo: 2×20'' sweet spot, 3×12'' limiar, 5×4'' potência crítica.", "de": "Belastungsspitze des ersten Zyklus: 2×20'' Sweet Spot, 3×12'' Schwelle, 5×4'' kritische Leistung.", "nl": "Piekbelasting van de eerste cyclus: 2×20'' sweet spot, 3×12'' drempel, 5×4'' kritisch vermogen.", "ja": "第1サイクルのオーバーロード：スイートスポット2×20''、閾値3×12''、クリティカルパワー5×4''。", "tr": "İlk döngünün yüklenmesi: 2×20'' sweet spot, 3×12'' eşik, 5×4'' kritik güç."}, "4": {"fr": "Allègement : volume divisé par deux. C''est pendant cette semaine que la FTP monte.", "en": "Lighter week: volume halved. This is the week your FTP rises.", "es": "Semana más ligera: volumen a la mitad. Es durante esta semana cuando sube la FTP.", "it": "Scarico: volume dimezzato. È durante questa settimana che la FTP sale.", "pt": "Alívio: volume pela metade. É durante esta semana que a FTP sobe.", "de": "Entlastung: Umfang halbiert. In dieser Woche steigt die FTP.", "nl": "Afbouw: volume gehalveerd. Tijdens deze week stijgt de FTP.", "ja": "軽めの週：ボリュームは半分。FTPが上がるのはこの週です。", "tr": "Hafifletme: hacim yarıya iniyor. FTP''nin yükseldiği hafta bu."}, "5": {"fr": "Deuxième cycle : 3×20'' sweet spot et 3×15'' au seuil, des blocs proches d''un CLM.", "en": "Second cycle: 3×20'' sweet spot and 3×15'' at threshold, blocks close to a TT.", "es": "Segundo ciclo: 3×20'' sweet spot y 3×15'' en umbral, bloques cercanos a una CRI.", "it": "Secondo ciclo: 3×20'' sweet spot e 3×15'' alla soglia, blocchi vicini a una crono.", "pt": "Segundo ciclo: 3×20'' sweet spot e 3×15'' no limiar, blocos próximos de um contrarrelógio.", "de": "Zweiter Zyklus: 3×20'' Sweet Spot und 3×15'' an der Schwelle, Blöcke nahe an einem Zeitfahren.", "nl": "Tweede cyclus: 3×20'' sweet spot en 3×15'' op drempel, blokken dicht bij een tijdrit.", "ja": "第2サイクル：スイートスポット3×20''と閾値3×15''、タイムトライアルに近いブロックです。", "tr": "İkinci döngü: 3×20'' sweet spot ve eşikte 3×15'', zamana karşıya yakın bloklar."}, "6": {"fr": "2×30'' sweet spot, 2×20'' au seuil : les efforts longs en TT qui font le plus progresser la FTP en aéro.", "en": "2×30'' sweet spot, 2×20'' at threshold: the long TT efforts that improve your FTP in aero the most.", "es": "2×30'' sweet spot, 2×20'' en umbral: los esfuerzos largos en TT que más hacen progresar la FTP en aero.", "it": "2×30'' sweet spot, 2×20'' alla soglia: gli sforzi lunghi in TT che fanno crescere di più la FTP in aero.", "pt": "2×30'' sweet spot, 2×20'' no limiar: os esforços longos em TT que mais fazem evoluir a FTP em aero.", "de": "2×30'' Sweet Spot, 2×20'' an der Schwelle: die langen Belastungen in TT, die die FTP in Aero-Position am stärksten verbessern.", "nl": "2×30'' sweet spot, 2×20'' op drempel: de lange inspanningen in TT die de FTP in aerohouding het meest laten vooruitgaan.", "ja": "スイートスポット2×30''、閾値2×20''：エアロでのFTPを最も伸ばす、TTでの長い努力です。", "tr": "2×30'' sweet spot, eşikte 2×20'': aero''da FTP''yi en çok geliştiren TT''deki uzun eforlar."}, "7": {"fr": "Pic du deuxième cycle : 3×25'' sweet spot, 3×20'' au seuil, 6×5'' puissance critique.", "en": "Peak of the second cycle: 3×25'' sweet spot, 3×20'' at threshold, 6×5'' critical power.", "es": "Pico del segundo ciclo: 3×25'' sweet spot, 3×20'' en umbral, 6×5'' potencia crítica.", "it": "Picco del secondo ciclo: 3×25'' sweet spot, 3×20'' alla soglia, 6×5'' potenza critica.", "pt": "Pico do segundo ciclo: 3×25'' sweet spot, 3×20'' no limiar, 6×5'' potência crítica.", "de": "Höhepunkt des zweiten Zyklus: 3×25'' Sweet Spot, 3×20'' an der Schwelle, 6×5'' kritische Leistung.", "nl": "Hoogtepunt van de tweede cyclus: 3×25'' sweet spot, 3×20'' op drempel, 6×5'' kritisch vermogen.", "ja": "第2サイクルのピーク：スイートスポット3×25''、閾値3×20''、クリティカルパワー6×5''。", "tr": "İkinci döngünün zirvesi: 3×25'' sweet spot, eşikte 3×20'', 6×5'' kritik güç."}, "8": {"fr": "Allègement avant le dernier cycle, blocs courts et une endurance TT.", "en": "Lighter week before the final cycle, short blocks and one TT endurance ride.", "es": "Semana más ligera antes del último ciclo, bloques cortos y una resistencia en TT.", "it": "Scarico prima dell''ultimo ciclo, blocchi brevi e un endurance in TT.", "pt": "Alívio antes do último ciclo, blocos curtos e um endurance em TT.", "de": "Entlastung vor dem letzten Zyklus, kurze Blöcke und eine TT-Grundlageneinheit.", "nl": "Afbouw voor de laatste cyclus, korte blokken en één duurtraining in TT.", "ja": "最後のサイクルの前の軽めの週、短いブロックとTTでのエンデュランス。", "tr": "Son döngüden önce hafifletme, kısa bloklar ve bir TT dayanıklılık."}, "9": {"fr": "Troisième cycle : 2×40'' en sweet spot et 2×25'' au seuil. La durée en TT dépasse celle de la plupart des CLM.", "en": "Third cycle: 2×40'' sweet spot and 2×25'' at threshold. Time in TT exceeds that of most TTs.", "es": "Tercer ciclo: 2×40'' en sweet spot y 2×25'' en umbral. La duración en TT supera la de la mayoría de las CRI.", "it": "Terzo ciclo: 2×40'' in sweet spot e 2×25'' alla soglia. La durata in TT supera quella della maggior parte delle crono.", "pt": "Terceiro ciclo: 2×40'' em sweet spot e 2×25'' no limiar. A duração em TT supera a da maioria dos contrarrelógios.", "de": "Dritter Zyklus: 2×40'' Sweet Spot und 2×25'' an der Schwelle. Die Dauer in TT übertrifft die der meisten Zeitfahren.", "nl": "Derde cyclus: 2×40'' sweet spot en 2×25'' op drempel. De duur in TT overtreft die van de meeste tijdritten.", "ja": "第3サイクル：スイートスポット2×40''と閾値2×25''。TTでの時間はほとんどのタイムトライアルを上回ります。", "tr": "Üçüncü döngü: sweet spot''ta 2×40'' ve eşikte 2×25''. TT''deki süre çoğu zamana karşı yarışının süresini aşıyor."}, "10": {"fr": "60'' d''affilée en sweet spot et 3×25'' au seuil : la FTP se travaille sur des durées de course.", "en": "60'' straight in sweet spot and 3×25'' at threshold: FTP is trained over race durations.", "es": "60'' seguidos en sweet spot y 3×25'' en umbral: la FTP se trabaja en duraciones de carrera.", "it": "60'' di fila in sweet spot e 3×25'' alla soglia: la FTP si allena su durate di gara.", "pt": "60'' seguidos em sweet spot e 3×25'' no limiar: a FTP é trabalhada em durações de prova.", "de": "60'' am Stück im Sweet Spot und 3×25'' an der Schwelle: Die FTP wird über Wettkampfdauer trainiert.", "nl": "60'' aan één stuk in sweet spot en 3×25'' op drempel: de FTP wordt getraind over wedstrijdduur.", "ja": "スイートスポットで60''連続と閾値3×25''：レースの時間でFTPを鍛えます。", "tr": "Sweet spot''ta kesintisiz 60'' ve eşikte 3×25'': FTP yarış sürelerinde çalışılıyor."}, "11": {"fr": "Pic du plan : 2×45'' sweet spot, 2×30'' au seuil, 6×6'' à 108 %. La semaine la plus dure, celle qui valide l''objectif.", "en": "Peak of the plan: 2×45'' sweet spot, 2×30'' at threshold, 6×6'' at 108 %. The hardest week, the one that validates the goal.", "es": "Pico del plan: 2×45'' sweet spot, 2×30'' en umbral, 6×6'' al 108 %. La semana más dura, la que valida el objetivo.", "it": "Picco del piano: 2×45'' sweet spot, 2×30'' alla soglia, 6×6'' al 108 %. La settimana più dura, quella che convalida l''obiettivo.", "pt": "Pico do plano: 2×45'' sweet spot, 2×30'' no limiar, 6×6'' a 108 %. A semana mais dura, a que valida o objetivo.", "de": "Höhepunkt des Plans: 2×45'' Sweet Spot, 2×30'' an der Schwelle, 6×6'' bei 108 %. Die härteste Woche, die das Ziel bestätigt.", "nl": "Hoogtepunt van het plan: 2×45'' sweet spot, 2×30'' op drempel, 6×6'' op 108 %. De zwaarste week, die het doel bevestigt.", "ja": "プランのピーク：スイートスポット2×45''、閾値2×30''、108 %で6×6''。最もきつい週で、目標を検証する週です。", "tr": "Planın zirvesi: 2×45'' sweet spot, eşikte 2×30'', %108''de 6×6''. En zor hafta, hedefi doğrulayan hafta."}, "12": {"fr": "Semaine allégée : tu récupères pour que ta nouvelle FTP en aéro s''exprime.", "en": "Lighter week: you recover so your new aero FTP can show.", "es": "Semana más ligera: recuperas para que tu nueva FTP en aero se exprese.", "it": "Settimana di scarico: recuperi perché la tua nuova FTP in aero si esprima.", "pt": "Semana mais leve: você recupera para que sua nova FTP em aero se expresse.", "de": "Entlastungswoche: Du erholst dich, damit deine neue FTP in Aero-Position zur Geltung kommt.", "nl": "Lichtere week: je herstelt zodat je nieuwe FTP in aerohouding tot uiting komt.", "ja": "軽めの週：回復して、エアロでの新しいFTPを発揮できるようにします。", "tr": "Hafif hafta: aero''daki yeni FTP''nin ortaya çıkması için toparlanıyorsun."}}'::jsonb) WHERE name_key = 'threshold_tt_12w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(coalesce(translations_json, '{}'::jsonb), '{weeks}', '{"1": {"fr": "Bases : sweet spot, PMA, seuil en 3×10'' et une sortie longue en TT. On construit les deux moteurs d''un CLM de 40 km : le seuil et l''endurance de position.", "en": "Base: sweet spot, VO2max, threshold as 3×10'' and a long ride in TT. We build the two engines of a 40 km TT: threshold and position endurance.", "es": "Bases: sweet spot, VO2max, umbral en 3×10'' y una salida larga en TT. Construimos los dos motores de una CRI de 40 km: el umbral y la resistencia en posición.", "it": "Basi: sweet spot, VO2max, soglia in 3×10'' e un''uscita lunga in TT. Costruiamo i due motori di una crono di 40 km: la soglia e la resistenza in posizione.", "pt": "Bases: sweet spot, VO2max, limiar em 3×10'' e um treino longo em TT. Construímos os dois motores de um contrarrelógio de 40 km: o limiar e a resistência na posição.", "de": "Grundlagen: Sweet Spot, VO2max, Schwelle in 3×10'' und eine lange Fahrt in TT. Wir bauen die beiden Motoren eines 40-km-Zeitfahrens auf: die Schwelle und die Positionsausdauer.", "nl": "Basis: sweet spot, VO2max, drempel in 3×10'' en een lange rit in TT. We bouwen de twee motoren van een tijdrit van 40 km op: de drempel en het uithoudingsvermogen in houding.", "ja": "基礎：スイートスポット、VO2max、閾値3×10''、TTでのロングライド。40 kmのタイムトライアルの2つのエンジン、閾値とポジションの持久力を築きます。", "tr": "Temeller: sweet spot, VO2max, eşikte 3×10'' ve TT''de bir uzun sürüş. 40 km''lik bir zamana karşının iki motorunu inşa ediyoruz: eşik ve pozisyon dayanıklılığı."}, "2": {"fr": "Les blocs s''allongent (3×15'' sweet spot, 3×12'' seuil). La PMA élève le plafond, le seuil la puissance que tu tiendras en course.", "en": "Blocks get longer (3×15'' sweet spot, 3×12'' threshold). VO2max raises the ceiling, threshold the power you''ll hold in the race.", "es": "Los bloques se alargan (3×15'' sweet spot, 3×12'' umbral). El VO2max eleva el techo; el umbral, la potencia que mantendrás en carrera.", "it": "I blocchi si allungano (3×15'' sweet spot, 3×12'' soglia). Il VO2max alza il tetto, la soglia la potenza che terrai in gara.", "pt": "Os blocos se alongam (3×15'' sweet spot, 3×12'' limiar). O VO2max eleva o teto, o limiar a potência que você vai segurar na prova.", "de": "Die Blöcke werden länger (3×15'' Sweet Spot, 3×12'' Schwelle). VO2max hebt die Obergrenze, die Schwelle die Leistung, die du im Rennen hältst.", "nl": "De blokken worden langer (3×15'' sweet spot, 3×12'' drempel). VO2max verhoogt het plafond, de drempel het vermogen dat je in de wedstrijd volhoudt.", "ja": "ブロックが伸びます（スイートスポット3×15''、閾値3×12''）。VO2maxは上限を引き上げ、閾値はレースで保てるパワーを引き上げます。", "tr": "Bloklar uzuyor (3×15'' sweet spot, eşikte 3×12''). VO2max tavanı, eşik ise yarışta tutacağın gücü yükseltir."}, "3": {"fr": "Surcharge du premier cycle : puissance critique, 3×15'' au seuil et 2 h 15 de sortie longue.", "en": "First-cycle overload: critical power, 3×15'' at threshold and a 2 h 15 long ride.", "es": "Sobrecarga del primer ciclo: potencia crítica, 3×15'' en umbral y 2 h 15 de salida larga.", "it": "Sovraccarico del primo ciclo: potenza critica, 3×15'' alla soglia e 2 h 15 di uscita lunga.", "pt": "Sobrecarga do primeiro ciclo: potência crítica, 3×15'' no limiar e 2 h 15 de treino longo.", "de": "Belastungsspitze des ersten Zyklus: kritische Leistung, 3×15'' an der Schwelle und 2 h 15 lange Fahrt.", "nl": "Piekbelasting van de eerste cyclus: kritisch vermogen, 3×15'' op drempel en een lange rit van 2 u 15.", "ja": "第1サイクルのオーバーロード：クリティカルパワー、閾値3×15''、2時間15分のロングライド。", "tr": "İlk döngünün yüklenmesi: kritik güç, eşikte 3×15'' ve 2 sa 15 uzun sürüş."}, "4": {"fr": "Allègement : volume réduit, intensité conservée sur des blocs courts. La fatigue s''efface, la forme monte.", "en": "Lighter week: reduced volume, intensity kept on short blocks. Fatigue fades, form rises.", "es": "Semana más ligera: volumen reducido, intensidad mantenida en bloques cortos. La fatiga se disipa, la forma sube.", "it": "Scarico: volume ridotto, intensità mantenuta su blocchi brevi. La fatica svanisce, la forma sale.", "pt": "Alívio: volume reduzido, intensidade mantida em blocos curtos. O cansaço some, a forma sobe.", "de": "Entlastung: weniger Umfang, Intensität auf kurzen Blöcken beibehalten. Die Müdigkeit verschwindet, die Form steigt.", "nl": "Afbouw: minder volume, intensiteit behouden op korte blokken. De vermoeidheid verdwijnt, de vorm stijgt.", "ja": "軽めの週：ボリュームを減らし、短いブロックで強度は維持。疲労が抜け、コンディションが上がります。", "tr": "Hafifletme: azaltılmış hacim, kısa bloklarda yoğunluk korunuyor. Yorgunluk siliniyor, form yükseliyor."}, "5": {"fr": "Deuxième cycle : 2×25'' sweet spot et 2×20'' au seuil. On s''approche de la moitié d''un CLM de 40 km d''un seul tenant.", "en": "Second cycle: 2×25'' sweet spot and 2×20'' at threshold. We get close to half of a 40 km TT in one go.", "es": "Segundo ciclo: 2×25'' sweet spot y 2×20'' en umbral. Nos acercamos a la mitad de una CRI de 40 km de una sola vez.", "it": "Secondo ciclo: 2×25'' sweet spot e 2×20'' alla soglia. Ci si avvicina a metà di una crono di 40 km tutta d''un fiato.", "pt": "Segundo ciclo: 2×25'' sweet spot e 2×20'' no limiar. Nos aproximamos da metade de um contrarrelógio de 40 km de uma vez só.", "de": "Zweiter Zyklus: 2×25'' Sweet Spot und 2×20'' an der Schwelle. Wir nähern uns der Hälfte eines 40-km-Zeitfahrens am Stück.", "nl": "Tweede cyclus: 2×25'' sweet spot en 2×20'' op drempel. We naderen de helft van een tijdrit van 40 km aan één stuk.", "ja": "第2サイクル：スイートスポット2×25''と閾値2×20''。40 kmのタイムトライアルの半分の時間に一続きで近づきます。", "tr": "İkinci döngü: 2×25'' sweet spot ve eşikte 2×20''. 40 km''lik bir zamana karşının yarısına kesintisiz yaklaşıyoruz."}, "6": {"fr": "3×20'' au seuil et sur-sous : apprendre à tenir la position quand le rythme change dans les relances et les faux plats.", "en": "3×20'' at threshold and over-unders: learning to hold the position when the pace changes on surges and false flats.", "es": "3×20'' en umbral y sobre-bajo: aprender a mantener la posición cuando el ritmo cambia en los cambios de ritmo y los falsos llanos.", "it": "3×20'' alla soglia e sopra-sotto: imparare a tenere la posizione quando il ritmo cambia nei rilanci e nei falsopiani.", "pt": "3×20'' no limiar e acima-abaixo: aprender a manter a posição quando o ritmo muda nas retomadas e nos falsos planos.", "de": "3×20'' an der Schwelle und Over-Under: lernen, die Position zu halten, wenn sich der Rhythmus bei Antritten und in flachen Anstiegen ändert.", "nl": "3×20'' op drempel en over-unders: leren de houding vast te houden als het ritme verandert bij versnellingen en op vals plat.", "ja": "閾値3×20''とオーバーアンダー：加速や緩い上りでリズムが変わってもポジションを保つことを学びます。", "tr": "Eşikte 3×20'' ve üst-altlar: ataklarda ve hafif rampalarda ritim değiştiğinde pozisyonu korumayı öğrenmek."}, "7": {"fr": "Pic du deuxième cycle : 60'' d''affilée en sweet spot et 2×30'' au seuil.", "en": "Peak of the second cycle: 60'' straight in sweet spot and 2×30'' at threshold.", "es": "Pico del segundo ciclo: 60'' seguidos en sweet spot y 2×30'' en umbral.", "it": "Picco del secondo ciclo: 60'' di fila in sweet spot e 2×30'' alla soglia.", "pt": "Pico do segundo ciclo: 60'' seguidos em sweet spot e 2×30'' no limiar.", "de": "Höhepunkt des zweiten Zyklus: 60'' am Stück im Sweet Spot und 2×30'' an der Schwelle.", "nl": "Hoogtepunt van de tweede cyclus: 60'' aan één stuk in sweet spot en 2×30'' op drempel.", "ja": "第2サイクルのピーク：スイートスポットで60''連続と閾値2×30''。", "tr": "İkinci döngünün zirvesi: sweet spot''ta kesintisiz 60'' ve eşikte 2×30''."}, "8": {"fr": "Allègement avant le cycle spécifique.", "en": "Lighter week before the specific cycle.", "es": "Semana más ligera antes del ciclo específico.", "it": "Scarico prima del ciclo specifico.", "pt": "Alívio antes do ciclo específico.", "de": "Entlastung vor dem spezifischen Zyklus.", "nl": "Afbouw voor de specifieke cyclus.", "ja": "特化サイクルの前の軽めの週。", "tr": "Özel döngüden önce hafifletme."}, "9": {"fr": "Cycle spécifique : 40'' d''affilée au seuil en TT. C''est la première vraie simulation de la course.", "en": "Specific cycle: 40'' straight at threshold in TT. This is the first real race simulation.", "es": "Ciclo específico: 40'' seguidos en umbral en TT. Es la primera simulación real de la carrera.", "it": "Ciclo specifico: 40'' di fila alla soglia in TT. È la prima vera simulazione della gara.", "pt": "Ciclo específico: 40'' seguidos no limiar em TT. É a primeira simulação real da prova.", "de": "Spezifischer Zyklus: 40'' am Stück an der Schwelle in TT. Das ist die erste echte Simulation des Rennens.", "nl": "Specifieke cyclus: 40'' aan één stuk op drempel in TT. Dit is de eerste echte simulatie van de wedstrijd.", "ja": "特化サイクル：TTで閾値40''連続。レースの初めての本格的なシミュレーションです。", "tr": "Özel döngü: TT''de eşikte kesintisiz 40''. Yarışın ilk gerçek simülasyonu bu."}, "10": {"fr": "75'' d''affilée en sweet spot et 2×30'' à 98 %. L''endurance de position rejoint la durée de la course.", "en": "75'' straight in sweet spot and 2×30'' at 98 %. Your position endurance reaches race duration.", "es": "75'' seguidos en sweet spot y 2×30'' al 98 %. La resistencia en posición alcanza la duración de la carrera.", "it": "75'' di fila in sweet spot e 2×30'' al 98 %. La resistenza in posizione raggiunge la durata della gara.", "pt": "75'' seguidos em sweet spot e 2×30'' a 98 %. A resistência na posição alcança a duração da prova.", "de": "75'' am Stück im Sweet Spot und 2×30'' bei 98 %. Die Positionsausdauer erreicht die Renndauer.", "nl": "75'' aan één stuk in sweet spot en 2×30'' op 98 %. Het uithoudingsvermogen in houding bereikt de wedstrijdduur.", "ja": "スイートスポットで75''連続と98 %で2×30''。ポジションの持久力がレースの時間に追いつきます。", "tr": "Sweet spot''ta kesintisiz 75'' ve %98''de 2×30''. Pozisyon dayanıklılığı yarışın süresine ulaşıyor."}, "11": {"fr": "Pic du plan : 50'' d''affilée à 96 % FTP en TT, l''allure d''un CLM de 40 km. C''est la répétition générale.", "en": "Peak of the plan: 50'' straight at 96 % FTP in TT, the pace of a 40 km TT. This is the dress rehearsal.", "es": "Pico del plan: 50'' seguidos al 96 % FTP en TT, el ritmo de una CRI de 40 km. Es el ensayo general.", "it": "Picco del piano: 50'' di fila al 96 % FTP in TT, il ritmo di una crono di 40 km. È la prova generale.", "pt": "Pico do plano: 50'' seguidos a 96 % FTP em TT, o ritmo de um contrarrelógio de 40 km. É o ensaio geral.", "de": "Höhepunkt des Plans: 50'' am Stück bei 96 % FTP in TT, das Tempo eines 40-km-Zeitfahrens. Das ist die Generalprobe.", "nl": "Hoogtepunt van het plan: 50'' aan één stuk op 96 % FTP in TT, het tempo van een tijdrit van 40 km. Dit is de generale repetitie.", "ja": "プランのピーク：TTでFTPの96 %を50''連続、40 kmのタイムトライアルのペースです。レースのリハーサルです。", "tr": "Planın zirvesi: TT''de FTP''nin %96''sında kesintisiz 50'', 40 km''lik bir zamana karşının temposu. Genel prova bu."}, "12": {"fr": "Affûtage : volume réduit, rappels courts à l''allure de course. Tu arrives frais le jour du CLM.", "en": "Taper: reduced volume, short reminders at race pace. You arrive fresh on TT day.", "es": "Puesta a punto: volumen reducido, recordatorios cortos a ritmo de carrera. Llegas fresco el día de la CRI.", "it": "Scarico: volume ridotto, richiami brevi al ritmo di gara. Arrivi fresco il giorno della crono.", "pt": "Polimento: volume reduzido, lembretes curtos no ritmo de prova. Você chega descansado no dia do contrarrelógio.", "de": "Tapering: weniger Umfang, kurze Erinnerungen im Wettkampftempo. Du gehst frisch ins Zeitfahren.", "nl": "Taperen: minder volume, korte herhalingen op wedstrijdtempo. Je komt fris aan de start van de tijdrit.", "ja": "調整（テーパー）：ボリュームを減らし、レースペースで短い確認を。タイムトライアル当日はフレッシュな状態で臨みます。", "tr": "Yarış öncesi yük azaltma: azaltılmış hacim, yarış temposunda kısa hatırlatmalar. Zamana karşı günü taze geliyorsun."}}'::jsonb) WHERE name_key = 'clm_long_12w_name';
UPDATE public.training_plans SET translations_json = jsonb_set(coalesce(translations_json, '{}'::jsonb), '{weeks}', '{"1": {"fr": "Adaptation : allure triathlon en 2×15'', tempo, PMA et 1 h 45 de sortie longue. On installe la position aux allures de la longue distance.", "en": "Adaptation: triathlon pace as 2×15'', tempo, VO2max and a 1 h 45 long ride. We settle the position at long-distance paces.", "es": "Adaptación: ritmo de triatlón en 2×15'', tempo, VO2max y 1 h 45 de salida larga. Asentamos la posición a los ritmos de la larga distancia.", "it": "Adattamento: ritmo triathlon in 2×15'', ritmo tempo, VO2max e 1 h 45 di uscita lunga. Fissiamo la posizione ai ritmi della lunga distanza.", "pt": "Adaptação: ritmo de triatlo em 2×15'', ritmo tempo, VO2max e 1 h 45 de treino longo. Fixamos a posição nos ritmos da longa distância.", "de": "Anpassung: Triathlontempo in 2×15'', Tempo, VO2max und 1 h 45 lange Fahrt. Wir festigen die Position im Tempo der Langdistanz.", "nl": "Aanpassing: triatlontempo in 2×15'', tempo, VO2max en een lange rit van 1 u 45. We leren de houding aan op de tempo''s van de lange afstand.", "ja": "適応：トライアスロンペースで2×15''、テンポ、VO2max、1時間45分のロングライド。ロングディスタンスのペースでポジションを定着させます。", "tr": "Uyum: triatlon temposunda 2×15'', tempo, VO2max ve 1 sa 45 uzun sürüş. Pozisyonu uzun mesafe temposunda oturtuyoruz."}, "2": {"fr": "Les blocs s''allongent et la sortie longue passe à 2 h 15. L''enjeu est la nuque et le bas du dos, qui fatiguent avant les jambes.", "en": "Blocks get longer and the long ride goes up to 2 h 15. The key is your neck and lower back, which tire before your legs.", "es": "Los bloques se alargan y la salida larga pasa a 2 h 15. El reto son la nuca y la zona lumbar, que se fatigan antes que las piernas.", "it": "I blocchi si allungano e l''uscita lunga passa a 2 h 15. La sfida sono il collo e la zona lombare, che si stancano prima delle gambe.", "pt": "Os blocos se alongam e o treino longo passa para 2 h 15. O desafio é a nuca e a lombar, que cansam antes das pernas.", "de": "Die Blöcke werden länger und die lange Fahrt steigt auf 2 h 15. Die Herausforderung sind Nacken und unterer Rücken, die vor den Beinen ermüden.", "nl": "De blokken worden langer en de lange rit gaat naar 2 u 15. De uitdaging zijn je nek en onderrug, die eerder vermoeid raken dan je benen.", "ja": "ブロックが伸び、ロングライドは2時間15分に。課題は首と腰で、脚より先に疲れます。", "tr": "Bloklar uzuyor ve uzun sürüş 2 sa 15''e çıkıyor. Mesele ense ve bel: bacaklardan önce yorulurlar."}, "3": {"fr": "Surcharge du premier cycle : 3×20'' à l''allure triathlon et 2 h 35 de sortie longue.", "en": "First-cycle overload: 3×20'' at triathlon pace and a 2 h 35 long ride.", "es": "Sobrecarga del primer ciclo: 3×20'' a ritmo de triatlón y 2 h 35 de salida larga.", "it": "Sovraccarico del primo ciclo: 3×20'' al ritmo triathlon e 2 h 35 di uscita lunga.", "pt": "Sobrecarga do primeiro ciclo: 3×20'' no ritmo de triatlo e 2 h 35 de treino longo.", "de": "Belastungsspitze des ersten Zyklus: 3×20'' im Triathlontempo und 2 h 35 lange Fahrt.", "nl": "Piekbelasting van de eerste cyclus: 3×20'' op triatlontempo en een lange rit van 2 u 35.", "ja": "第1サイクルのオーバーロード：トライアスロンペースで3×20''、2時間35分のロングライド。", "tr": "İlk döngünün yüklenmesi: triatlon temposunda 3×20'' ve 2 sa 35 uzun sürüş."}, "4": {"fr": "Allègement : une séance en moins. La récupération prépare le deuxième cycle.", "en": "Lighter week: one session fewer. Recovery prepares the second cycle.", "es": "Semana más ligera: una sesión menos. La recuperación prepara el segundo ciclo.", "it": "Scarico: una seduta in meno. Il recupero prepara il secondo ciclo.", "pt": "Alívio: uma sessão a menos. A recuperação prepara o segundo ciclo.", "de": "Entlastung: eine Einheit weniger. Die Erholung bereitet den zweiten Zyklus vor.", "nl": "Afbouw: één training minder. Het herstel bereidt de tweede cyclus voor.", "ja": "軽めの週：セッションを1回減らします。回復が第2サイクルの準備になります。", "tr": "Hafifletme: bir antrenman eksik. Toparlanma ikinci döngüyü hazırlıyor."}, "5": {"fr": "Deuxième cycle : 2×30'' à l''allure 70.3 et 2×30'' au tempo. Les blocs prennent la durée d''une partie de course.", "en": "Second cycle: 2×30'' at 70.3 pace and 2×30'' at tempo. Blocks take on the length of a section of the race.", "es": "Segundo ciclo: 2×30'' a ritmo de 70.3 y 2×30'' a tempo. Los bloques adquieren la duración de una parte de la carrera.", "it": "Secondo ciclo: 2×30'' al ritmo 70.3 e 2×30'' al ritmo tempo. I blocchi assumono la durata di una parte di gara.", "pt": "Segundo ciclo: 2×30'' no ritmo de 70.3 e 2×30'' no ritmo tempo. Os blocos ganham a duração de uma parte da prova.", "de": "Zweiter Zyklus: 2×30'' im 70.3-Tempo und 2×30'' im Tempo. Die Blöcke erreichen die Dauer eines Rennabschnitts.", "nl": "Tweede cyclus: 2×30'' op 70.3-tempo en 2×30'' op tempo. De blokken krijgen de duur van een deel van de wedstrijd.", "ja": "第2サイクル：70.3のペースで2×30''、テンポで2×30''。ブロックがレースの一部分の長さになります。", "tr": "İkinci döngü: 70.3 temposunda 2×30'' ve tempoda 2×30''. Bloklar yarışın bir bölümünün süresine ulaşıyor."}, "6": {"fr": "45'' d''affilée à l''allure triathlon. Une position tenue sans crispation laisse des jambes pour la course à pied.", "en": "45'' straight at triathlon pace. A position held without tension leaves legs for the run.", "es": "45'' seguidos a ritmo de triatlón. Una posición mantenida sin tensión te deja piernas para la carrera a pie.", "it": "45'' di fila al ritmo triathlon. Una posizione tenuta senza tensioni lascia gambe per la corsa.", "pt": "45'' seguidos no ritmo de triatlo. Uma posição sustentada sem tensão deixa pernas para a corrida.", "de": "45'' am Stück im Triathlontempo. Eine Position ohne Verkrampfung lässt dir Beine für den Lauf.", "nl": "45'' aan één stuk op triatlontempo. Een houding zonder verkramping laat je benen over voor het lopen.", "ja": "トライアスロンペースで45''連続。力まずに保ったポジションは、ランのための脚を残します。", "tr": "Triatlon temposunda kesintisiz 45''. Kasılmadan tutulan pozisyon koşu için bacak bırakır."}, "7": {"fr": "Pic du deuxième cycle : 2×40'' à l''allure triathlon, 60'' d''affilée au tempo, 2 h d''affilée en TT.", "en": "Peak of the second cycle: 2×40'' at triathlon pace, 60'' straight at tempo, 2 h straight in TT.", "es": "Pico del segundo ciclo: 2×40'' a ritmo de triatlón, 60'' seguidos a tempo, 2 h seguidas en TT.", "it": "Picco del secondo ciclo: 2×40'' al ritmo triathlon, 60'' di fila al ritmo tempo, 2 h di fila in TT.", "pt": "Pico do segundo ciclo: 2×40'' no ritmo de triatlo, 60'' seguidos no ritmo tempo, 2 h seguidas em TT.", "de": "Höhepunkt des zweiten Zyklus: 2×40'' im Triathlontempo, 60'' am Stück im Tempo, 2 h am Stück in TT.", "nl": "Hoogtepunt van de tweede cyclus: 2×40'' op triatlontempo, 60'' aan één stuk op tempo, 2 u aan één stuk in TT.", "ja": "第2サイクルのピーク：トライアスロンペースで2×40''、テンポで60''連続、TTで2時間連続。", "tr": "İkinci döngünün zirvesi: triatlon temposunda 2×40'', tempoda kesintisiz 60'', TT''de kesintisiz 2 sa."}, "8": {"fr": "Allègement avant le cycle spécifique.", "en": "Lighter week before the specific cycle.", "es": "Semana más ligera antes del ciclo específico.", "it": "Scarico prima del ciclo specifico.", "pt": "Alívio antes do ciclo específico.", "de": "Entlastung vor dem spezifischen Zyklus.", "nl": "Afbouw voor de specifieke cyclus.", "ja": "特化サイクルの前の軽めの週。", "tr": "Özel döngüden önce hafifletme."}, "9": {"fr": "Cycle spécifique : 60'' d''affilée à l''allure triathlon et 2 h 10 d''affilée en sortie longue.", "en": "Specific cycle: 60'' straight at triathlon pace and 2 h 10 straight on the long ride.", "es": "Ciclo específico: 60'' seguidos a ritmo de triatlón y 2 h 10 seguidas en la salida larga.", "it": "Ciclo specifico: 60'' di fila al ritmo triathlon e 2 h 10 di fila nell''uscita lunga.", "pt": "Ciclo específico: 60'' seguidos no ritmo de triatlo e 2 h 10 seguidas no treino longo.", "de": "Spezifischer Zyklus: 60'' am Stück im Triathlontempo und 2 h 10 am Stück auf der langen Fahrt.", "nl": "Specifieke cyclus: 60'' aan één stuk op triatlontempo en 2 u 10 aan één stuk tijdens de lange rit.", "ja": "特化サイクル：トライアスロンペースで60''連続、ロングライドで2時間10分連続。", "tr": "Özel döngü: triatlon temposunda kesintisiz 60'' ve uzun sürüşte kesintisiz 2 sa 10."}, "10": {"fr": "2×45'' à l''allure 70.3 et 75'' au tempo : la position se travaille aux durées du vélo d''un Ironman.", "en": "2×45'' at 70.3 pace and 75'' at tempo: the position is trained over the durations of an Ironman bike leg.", "es": "2×45'' a ritmo de 70.3 y 75'' a tempo: la posición se trabaja en las duraciones del segmento ciclista de un Ironman.", "it": "2×45'' al ritmo 70.3 e 75'' al ritmo tempo: la posizione si allena sulle durate della frazione bici di un Ironman.", "pt": "2×45'' no ritmo de 70.3 e 75'' no ritmo tempo: a posição é trabalhada nas durações do ciclismo de um Ironman.", "de": "2×45'' im 70.3-Tempo und 75'' im Tempo: Die Position wird über die Dauer einer Ironman-Radstrecke trainiert.", "nl": "2×45'' op 70.3-tempo en 75'' op tempo: de houding wordt getraind over de duur van een Ironman-fietsproef.", "ja": "70.3のペースで2×45''、テンポで75''：アイアンマンのバイクの時間でポジションを鍛えます。", "tr": "70.3 temposunda 2×45'' ve tempoda 75'': pozisyon bir Ironman bisikletinin sürelerinde çalışılıyor."}, "11": {"fr": "Pic du plan : 90'' d''affilée à l''allure 70.3 et 2 h 30 d''affilée en TT. C''est la simulation de course.", "en": "Peak of the plan: 90'' straight at 70.3 pace and 2 h 30 straight in TT. This is the race simulation.", "es": "Pico del plan: 90'' seguidos a ritmo de 70.3 y 2 h 30 seguidas en TT. Es la simulación de carrera.", "it": "Picco del piano: 90'' di fila al ritmo 70.3 e 2 h 30 di fila in TT. È la simulazione di gara.", "pt": "Pico do plano: 90'' seguidos no ritmo de 70.3 e 2 h 30 seguidas em TT. É a simulação de prova.", "de": "Höhepunkt des Plans: 90'' am Stück im 70.3-Tempo und 2 h 30 am Stück in TT. Das ist die Wettkampfsimulation.", "nl": "Hoogtepunt van het plan: 90'' aan één stuk op 70.3-tempo en 2 u 30 aan één stuk in TT. Dit is de wedstrijdsimulatie.", "ja": "プランのピーク：70.3のペースで90''連続、TTで2時間30分連続。レースのシミュレーションです。", "tr": "Planın zirvesi: 70.3 temposunda kesintisiz 90'' ve TT''de kesintisiz 2 sa 30. Yarış simülasyonu bu."}, "12": {"fr": "Affûtage : volume minimal, rappels d''allure. Tu arrives frais sur la ligne de départ.", "en": "Taper: minimal volume, pace reminders. You arrive fresh on the start line.", "es": "Puesta a punto: volumen mínimo, recordatorios de ritmo. Llegas fresco a la línea de salida.", "it": "Scarico: volume minimo, richiami di ritmo. Arrivi fresco sulla linea di partenza.", "pt": "Polimento: volume mínimo, lembretes de ritmo. Você chega descansado à linha de largada.", "de": "Tapering: minimaler Umfang, Tempo-Erinnerungen. Du kommst frisch an die Startlinie.", "nl": "Taperen: minimaal volume, korte tempoherhalingen. Je komt fris aan de startlijn.", "ja": "調整（テーパー）：ボリュームは最小、ペースの確認を少し。スタートラインにはフレッシュな状態で立ちます。", "tr": "Yarış öncesi yük azaltma: minimum hacim, tempo hatırlatmaları. Start çizgisine taze geliyorsun."}}'::jsonb) WHERE name_key = 'triathlon_long_12w_name';
